// ---- নতুন ডিভাইসে লগইন: ইমেইল OTP ----
const loginOtps = new Map();
const devIpHits = new Map();
setInterval(function () {
  const now = Date.now();
  loginOtps.forEach(function (v, k) { if (v.expires < now) loginOtps.delete(k); });
  devIpHits.forEach(function (v, k) { if (now - v.first > 15 * 60 * 1000) devIpHits.delete(k); });
}, 5 * 60 * 1000).unref();
function getCookie(req, name) {
  const parts = String(req.headers.cookie || '').split(';');
  for (const p0 of parts) {
    const p = p0.trim();
    if (p.indexOf(name + '=') === 0) return decodeURIComponent(p.slice(name.length + 1));
  }
  return '';
}
function devHash(tok) { return crypto.createHash('sha256').update('ffx-dev:' + tok).digest('hex'); }
function deviceTrusted(req, user) {
  const tok = getCookie(req, 'ffx_dev');
  if (!/^[a-f0-9]{48}$/.test(tok)) return false;
  const h = devHash(tok);
  return Array.isArray(user.devices) && user.devices.some(function (d) { return d.h === h; });
}
function trustDevice(req, res, user) {
  let tok = getCookie(req, 'ffx_dev');
  if (!/^[a-f0-9]{48}$/.test(tok)) tok = crypto.randomBytes(24).toString('hex');
  const h = devHash(tok);
  if (!Array.isArray(user.devices)) user.devices = [];
  if (!user.devices.some(function (d) { return d.h === h; })) {
    user.devices.push({ h: h, at: new Date().toISOString() });
    if (user.devices.length > 8) user.devices = user.devices.slice(-8);
    saveCustomers();
  }
  const c = 'ffx_dev=' + tok + '; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000' + (process.env.NODE_ENV === 'production' ? '; Secure' : '');
  res.setHeader('Set-Cookie', [].concat(res.getHeader('Set-Cookie') || [], c));
}
function maskEmail(e) { const p = String(e || '').split('@'); return p[0].slice(0, 2) + '***@' + (p[1] || ''); }

// ---- মাসিক লিডারবোর্ড: সম্পন্ন (Completed) অর্ডারের টাকা = পয়েন্ট, প্রতি মাসে (বাংলাদেশ সময়) ০ থেকে শুরু ----
let lbCache = { key: '', at: 0, rows: [] };
function bdMonthRange() {
  const BD = 6 * 60 * 60 * 1000;
  const now = new Date(Date.now() + BD);
  const y = now.getUTCFullYear(), m = now.getUTCMonth();
  return { key: y + '-' + (m + 1), start: new Date(Date.UTC(y, m, 1) - BD), end: new Date(Date.UTC(y, m + 1, 1) - BD) };
}
function lbDbReady() {
  try { return require('mongoose').connection.readyState === 1; } catch (e) { return false; }
}
async function monthlyRanking() {
  const range = bdMonthRange();
  if (lbCache.key === range.key && Date.now() - lbCache.at < 60000) return lbCache;
  if (!lbDbReady()) return { key: range.key, at: 0, rows: [] };
  const { Order } = require('./models');
  const rows = await Order.aggregate([
    { $match: { status: 'Completed', createdAt: { $gte: range.start, $lt: range.end } } },
    { $group: { _id: '$customerId', points: { $sum: '$price' } } },
    { $match: { points: { $gt: 0 } } },
    { $sort: { points: -1, _id: 1 } }
  ]);
  lbCache = { key: range.key, at: Date.now(), rows: rows.map(function (r) { return { id: String(r._id), points: Math.round(r.points) }; }) };
  return lbCache;
}
async function totalSpentOf(customerId) {
  if (!lbDbReady()) return 0;
  const { Order } = require('./models');
  const r = await Order.aggregate([
    { $match: { customerId: String(customerId), status: 'Completed' } },
    { $group: { _id: null, t: { $sum: '$price' } } }
  ]);
  return r.length ? Math.round(r[0].t) : 0;
}

// ---- সর্বশেষ কমপ্লিট অর্ডার (Live) — নাম মাস্ক করা, UID/ফোন/ইমেইল পাঠানো হয় না ----
let liveCache = { at: 0, rows: [] };
function maskName(n) {
  const parts = String(n || 'Customer').trim().split(/\s+/).filter(Boolean).slice(0, 3);
  if (!parts.length) return 'Customer***';
  if (parts.length === 1) { const w = Array.from(parts[0]); return w.slice(0, Math.min(3, Math.max(1, w.length - 1))).join('') + '***'; }
  return parts[0] + ' ' + parts.slice(1).map(function (p) { return Array.from(p)[0] + '***'; }).join(' ');
}
async function liveOrders() {
  if (Date.now() - liveCache.at < 8000) return liveCache.rows;
  if (!lbDbReady()) return [];
  const { Order } = require('./models');
  const docs = await Order.find({ status: 'Completed' }).sort({ updatedAt: -1 }).limit(15)
    .select('customerId packageName price updatedAt').lean();
  const rows = docs.map(function (o) {
    const u = customers.find(function (c) { return c.id === String(o.customerId); });
    return {
      name: maskName(u && u.name),
      avatar: (u && u.avatar) || '',
      pkg: String(o.packageName || '').slice(0, 60),
      price: Math.round(o.price || 0),
      at: o.updatedAt
    };
  });
  liveCache = { at: Date.now(), rows: rows };
  return rows;
}

// ---- প্রোফাইল ছবি আপলোড (ছোট JPEG; আলাদা জায়গায় সেভ, customers ডাটা ভারী হয় না) ----
const AV_DIR = path.join(DATA_DIR, 'avatars');
const avLast = new Map();
function avSave(id, buf) {
  try { fs.mkdirSync(AV_DIR, { recursive: true }); fs.writeFileSync(path.join(AV_DIR, id + '.jpg'), buf); } catch (e) { console.error('Avatar file save error:', e && e.message); }
  if (custColl) {
    custColl.updateOne({ _id: 'avatar:' + id }, { $set: { data: buf.toString('base64'), at: Date.now() } }, { upsert: true })
      .catch(function (e) { console.error('Avatar MongoDB save error:', e && e.message); });
  }
}
async function avLoad(id) {
  try { return fs.readFileSync(path.join(AV_DIR, id + '.jpg')); } catch (e) {}
  if (custColl) {
    try {
      const d = await custColl.findOne({ _id: 'avatar:' + id });
      if (d && d.data) return Buffer.from(d.data, 'base64');
    } catch (e) {}
  }
  return null;
}

async function handleApi(req, res, pathname) {
  try {
    if (req.method === 'GET' && pathname === '/api/wallet/payment-info') {
      res.setHeader('Cache-Control', 'no-store');
      return sendJson(res, 200, await api.paymentInfo());
    }
    if (req.method === 'GET' && pathname === '/api/leaderboard') {
      res.setHeader('Cache-Control', 'no-store');
      const rk = await monthlyRanking();
      const top = rk.rows.slice(0, 10).map(function (r, i) {
        const u = customers.find(function (c) { return c.id === r.id; });
        return { rank: i + 1, name: u ? String(u.name || 'Customer').slice(0, 18) : 'Customer', avatar: (u && u.avatar) || '', points: r.points };
      });
      let me = null;
      const cu = customerFromRequest(req);
      if (cu) {
        const idx = rk.rows.findIndex(function (r) { return r.id === cu.id; });
        me = { rank: idx >= 0 ? idx + 1 : 0, points: idx >= 0 ? rk.rows[idx].points : 0, total: await totalSpentOf(cu.id) };
      }
      return sendJson(res, 200, { month: rk.key, top: top, me: me });
    }
    if (req.method === 'POST' && pathname.indexOf('/api/tg/') === 0) {
      const tg = require('./services/telegram');
      const sec = tg.webhookSecret();
      if (!sec || pathname !== '/api/tg/' + sec || req.headers['x-telegram-bot-api-secret-token'] !== sec) return sendJson(res, 404, { error: 'Not found' });
      let upd = null;
      try { upd = await readJson(req, 262144); } catch (e) {}
      sendJson(res, 200, { ok: true });
      if (upd) tg.handleUpdate(upd).catch(function (e) { console.error('tg update error:', e && e.message); });
      return;
    }
    if (req.method === 'GET' && pathname.indexOf('/api/avatar/') === 0) {
      const id = pathname.slice('/api/avatar/'.length);
      if (!/^[0-9a-f-]{36}$/i.test(id)) return sendJson(res, 404, { error: 'Not found' });
      const buf = await avLoad(id);
      if (!buf) return sendJson(res, 404, { error: 'Not found' });
      res.writeHead(200, { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400', 'X-Content-Type-Options': 'nosniff', 'Content-Length': buf.length });
      return res.end(buf);
    }
    if (req.method === 'POST' && pathname === '/api/auth/avatar') {
      const cu = customerFromRequest(req);
      if (!cu) return sendJson(res, 401, { error: 'আগে লগইন করুন' });
      if (Date.now() - (avLast.get(cu.id) || 0) < 3000) return sendJson(res, 429, { error: 'একটু পরে আবার চেষ্টা করুন' });
      avLast.set(cu.id, Date.now());
      const body = await readJson(req, 100000);
      const m = /^data:image\/jpeg;base64,([A-Za-z0-9+\/=]+)$/.exec(String(body.image || ''));
      if (!m) return sendJson(res, 400, { error: 'ছবির ফরম্যাট ঠিক নেই' });
      const buf = Buffer.from(m[1], 'base64');
      if (buf.length < 500 || buf.length > 70000 || buf[0] !== 0xFF || buf[1] !== 0xD8 || buf[2] !== 0xFF) return sendJson(res, 400, { error: 'ছবিটা ঠিক নেই বা অনেক বড়' });
      avSave(cu.id, buf);
      cu.avatar = '/api/avatar/' + cu.id + '?v=' + Date.now().toString(36);
      cu.avatarCustom = true;
      saveCustomers();
      return sendJson(res, 200, { ok: true, avatar: cu.avatar });
    }
    if (req.method === 'GET' && pathname === '/api/live-orders') {
      res.setHeader('Cache-Control', 'no-store');
      return sendJson(res, 200, { orders: await liveOrders() });
    }
    if (await api.handle(req, res, pathname)) return;

    if (req.method === 'GET' && pathname === '/api/auth/me') {
      const user = customerFromRequest(req);
      return sendJson(res, 200, { loggedIn: !!user, user: user ? await withBalance(customerPublic(user)) : null });
    }
    if (req.method === 'POST' && pathname === '/api/auth/register') {
      if (MONGO_URI_CUST && !custColl) return sendJson(res, 503, { error: 'সার্ভার প্রস্তুত হচ্ছে। ১০–২০ সেকেন্ড পরে আবার চেষ্টা করুন।' });
      const body = await readJson(req, 8192);
      const name = String(body.name || '').trim().slice(0, 60);
      const email = String(body.email || '').trim().toLowerCase().slice(0, 160);
      const password = String(body.password || '');
      if (name.length < 2) return sendJson(res, 400, { error: 'নাম কমপক্ষে ২ অক্ষরের হতে হবে' });
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return sendJson(res, 400, { error: 'সঠিক ইমেইল দিন' });
      if (password.length < 8 || password.length > 128) return sendJson(res, 400, { error: 'পাসওয়ার্ড ৮–১২৮ অক্ষরের হতে হবে' });
      const phone = normPhone(body.phone);
      if (!phone) return sendJson(res, 400, { error: 'সঠিক বাংলাদেশি মোবাইল নাম্বার দিন (যেমন 01XXXXXXXXX)' });
      if (customers.some(u => u.email === email)) return sendJson(res, 409, { error: 'এই ইমেইলে অ্যাকাউন্ট আগে থেকেই আছে। Login করুন।' });
      const salt = crypto.randomBytes(16).toString('hex');
      const hash = await passwordHash(password, salt);
      const user = { id: crypto.randomUUID(), name, email, salt, passwordHash: hash, phone: phone, createdAt: new Date().toISOString() };
      customers.push(user);
      saveCustomers();
      const token = crypto.randomBytes(32).toString('hex');
      customerSessions.set(token, { userId: user.id, expires: Date.now() + 7 * 24 * 60 * 60 * 1000 });
      setCustomerCookie(res, token); trustDevice(req, res, user);
      return sendJson(res, 201, { loggedIn: true, user: await withBalance(customerPublic(user)) });
    }
    if (req.method === 'POST' && pathname === '/api/auth/login') {
      if (MONGO_URI_CUST && !custColl) return sendJson(res, 503, { error: 'সার্ভার প্রস্তুত হচ্ছে। ১০–২০ সেকেন্ড পরে আবার চেষ্টা করুন।' });
      const body = await readJson(req, 8192);
      const email = String(body.email || '').trim().toLowerCase();
      const password = String(body.password || '');
      const key = customerLoginKey(email, clientIp(req));
      const FORGOT_MSG = 'পরপর ৩ বার ভুল হয়েছে। "পাসওয়ার্ড ভুলে গেছেন?" চেপে ইমেইলে OTP নিয়ে নতুন পাসওয়ার্ড দিন।';
      const wait = customerLoginLock(key);
      if (wait) return sendJson(res, 429, { error: FORGOT_MSG, forgot: true, retryAfter: Math.ceil(wait / 1000) });
      const user = customers.find(u => u.email === email);
      let ok = false;
      if (user) {
        ok = safeEq(await passwordHash(password, user.salt), user.passwordHash);
        const trimmed = password.trim();
        if (!ok && trimmed && trimmed !== password) ok = safeEq(await passwordHash(trimmed, user.salt), user.passwordHash);
      } else {
        await passwordHash(password || 'invalid-password', 'ffx-fixed-dummy-salt');
      }
      if (!ok) {
        const count = customerLoginFailed(key);
        if (count >= 3) return sendJson(res, 429, { error: FORGOT_MSG, forgot: true, attempts: count, retryAfter: Math.ceil(LOCK_MS / 1000) });
        return sendJson(res, 401, { error: 'ইমেইল অথবা পাসওয়ার্ড সঠিক নয়। Google দিয়ে খুলে থাকলে Google বাটন ব্যবহার করুন। ভুলের চেষ্টা ' + count + '/3', attempts: count });
      }
      customerLoginFails.delete(key);
      if (!deviceTrusted(req, user)) {
        if (!mailConfigured()) return sendJson(res, 503, { error: 'নতুন ডিভাইসের OTP পাঠানো যাচ্ছে না। Support-এর সঙ্গে যোগাযোগ করুন।', support: true });
        const nowD = Date.now(), ipD = clientIp(req);
        const hd = devIpHits.get(ipD) || { n: 0, first: nowD };
        if (nowD - hd.first > 15 * 60 * 1000) { hd.n = 0; hd.first = nowD; }
        if (++hd.n > 10) return sendJson(res, 429, { error: 'অনেকবার চেষ্টা হয়েছে। ১৫ মিনিট পরে আবার চেষ্টা করুন।', support: true });
        devIpHits.set(ipD, hd);
        const challenge = crypto.randomBytes(16).toString('hex');
        const otpD = String(crypto.randomInt(100000, 1000000));
        loginOtps.set(challenge, { userId: user.id, hash: otpHash(user.email, otpD), expires: nowD + OTP_TTL_MS, tries: 0, sentAt: nowD, resends: 0 });
        try { await sendOtpMail(user.email, otpD, 'login'); }
        catch (e) {
          loginOtps.delete(challenge);
          console.error('Login OTP mail error:', e && e.message);
          return sendJson(res, 502, { error: 'ইমেইল পাঠানো যায়নি। কিছুক্ষণ পরে আবার চেষ্টা করুন।', support: true });
        }
        return sendJson(res, 202, { needOtp: true, challenge: challenge, emailHint: maskEmail(user.email) });
      }
      const token = crypto.randomBytes(32).toString('hex');
      customerSessions.set(token, { userId: user.id, expires: Date.now() + 7 * 24 * 60 * 60 * 1000 });
      setCustomerCookie(res, token); trustDevice(req, res, user);
      return sendJson(res, 200, { loggedIn: true, user: await withBalance(customerPublic(user)) });
    }
    if (req.method === 'POST' && pathname === '/api/auth/google') {
      if (MONGO_URI_CUST && !custColl) return sendJson(res, 503, { error: 'সার্ভার প্রস্তুত হচ্ছে। ১০–২০ সেকেন্ড পরে আবার চেষ্টা করুন।' });
      const body = await readJson(req, 8192);
      const cred = String(body.credential || '');
      if (!GOOGLE_CLIENT_ID || cred.length < 50) return sendJson(res, 400, { error: 'Google লগইন করা যায়নি' });
      let info = null;
      try { info = await googleVerify(cred); } catch (e) { console.error('Google verify error:', e && e.message); }
      const okIss = info && (info.iss === 'accounts.google.com' || info.iss === 'https://accounts.google.com');
      const okMail = info && (info.email_verified === true || info.email_verified === 'true');
      if (!info || info.aud !== GOOGLE_CLIENT_ID || !okIss || !okMail || !info.email || Number(info.exp) * 1000 < Date.now()) {
        return sendJson(res, 401, { error: 'Google লগইন যাচাই করা যায়নি। আবার চেষ্টা করুন।' });
      }
      const email = String(info.email).trim().toLowerCase().slice(0, 160);
      const pic = /^https:\/\/[a-z0-9.-]+\.googleusercontent\.com\//i.test(String(info.picture || '')) ? String(info.picture).slice(0, 400) : '';
      let user = customers.find(u => u.email === email);
      if (!user) {
        let nm = String(info.name || '').trim().slice(0, 60);
        if (nm.length < 2) nm = email.split('@')[0].slice(0, 60);
        user = { id: crypto.randomUUID(), name: nm, email, salt: crypto.randomBytes(16).toString('hex'), passwordHash: crypto.randomBytes(32).toString('hex'), avatar: pic, createdAt: new Date().toISOString() };
        customers.push(user);
        saveCustomers();
      } else if (pic && !user.avatarCustom && user.avatar !== pic) {
        user.avatar = pic;
        saveCustomers();
      }
      const token = crypto.randomBytes(32).toString('hex');
      customerSessions.set(token, { userId: user.id, expires: Date.now() + 7 * 24 * 60 * 60 * 1000 });
      setCustomerCookie(res, token); trustDevice(req, res, user);
      return sendJson(res, 200, { loggedIn: true, user: await withBalance(customerPublic(user)) });
    }
    if (req.method === 'POST' && pathname === '/api/auth/login-otp') {
      const body = await readJson(req, 2048);
      const ch = String(body.challenge || '');
      const otp = String(body.otp || '').trim();
      const rec = loginOtps.get(ch);
      if (!rec || rec.expires < Date.now()) { loginOtps.delete(ch); return sendJson(res, 400, { error: 'OTP-র মেয়াদ শেষ। আবার লগইন করুন।', restart: true }); }
      const user = customers.find(u => u.id === rec.userId);
      if (!user) { loginOtps.delete(ch); return sendJson(res, 400, { error: 'আবার লগইন করুন।', restart: true }); }
      if (!/^\d{6}$/.test(otp)) return sendJson(res, 400, { error: 'OTP ৬ সংখ্যার হতে হবে' });
      if (++rec.tries > 5) { loginOtps.delete(ch); return sendJson(res, 429, { error: 'অনেকবার ভুল OTP দেওয়া হয়েছে। Support-এর সঙ্গে যোগাযোগ করুন।', support: true, restart: true }); }
      if (!safeEq(rec.hash, otpHash(user.email, otp))) return sendJson(res, 400, { error: 'OTP ঠিক নয় (' + rec.tries + '/5)', support: rec.tries >= 3 });
      loginOtps.delete(ch);
      const token = crypto.randomBytes(32).toString('hex');
      customerSessions.set(token, { userId: user.id, expires: Date.now() + 7 * 24 * 60 * 60 * 1000 });
      setCustomerCookie(res, token); trustDevice(req, res, user);
      return sendJson(res, 200, { loggedIn: true, user: await withBalance(customerPublic(user)) });
    }
    if (req.method === 'POST' && pathname === '/api/auth/login-otp-resend') {
      const body = await readJson(req, 2048);
      const ch = String(body.challenge || '');
      const rec = loginOtps.get(ch);
      const now = Date.now();
      if (!rec || rec.expires < now) { loginOtps.delete(ch); return sendJson(res, 400, { error: 'মেয়াদ শেষ। আবার লগইন করুন।', restart: true }); }
      const user = customers.find(u => u.id === rec.userId);
      if (!user) { loginOtps.delete(ch); return sendJson(res, 400, { error: 'আবার লগইন করুন।', restart: true }); }
      if (now - rec.sentAt < 55000) return sendJson(res, 429, { error: 'এক মিনিট পরে আবার OTP চান।' });
      if (++rec.resends > 3) { loginOtps.delete(ch); return sendJson(res, 429, { error: 'অনেকবার OTP চাওয়া হয়েছে। Support-এর সঙ্গে যোগাযোগ করুন।', support: true, restart: true }); }
      const otp = String(crypto.randomInt(100000, 1000000));
      rec.hash = otpHash(user.email, otp); rec.sentAt = now; rec.tries = 0; rec.expires = now + OTP_TTL_MS;
      try { await sendOtpMail(user.email, otp, 'login'); }
      catch (e) { console.error('Login OTP resend error:', e && e.message); return sendJson(res, 502, { error: 'ইমেইল পাঠানো যায়নি। কিছুক্ষণ পরে আবার চেষ্টা করুন।', support: true }); }
      return sendJson(res, 200, { ok: true });
    }
    if (req.method === 'POST' && pathname === '/api/auth/phone') {
      const me = customerFromRequest(req);
      if (!me) return sendJson(res, 401, { error: 'আগে লগইন করুন' });
      const body = await readJson(req, 2048);
      const phone = normPhone(body.phone);
      if (!phone) return sendJson(res, 400, { error: 'সঠিক বাংলাদেশি মোবাইল নাম্বার দিন (যেমন 01XXXXXXXXX)' });
      me.phone = phone;
      saveCustomers();
      return sendJson(res, 200, { ok: true, user: await withBalance(customerPublic(me)) });
    }
    if (req.method === 'POST' && pathname === '/api/auth/logout') {
      const token = customerCookieToken(req);
      if (token) customerSessions.delete(token);
      res.setHeader('Set-Cookie', 'ffx_customer=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0' + (process.env.NODE_ENV === 'production' ? '; Secure' : ''));
      return sendJson(res, 200, { loggedIn: false });
    }

    if (req.method === 'POST' && pathname === '/api/auth/forgot') {
      const body = await readJson(req, 4096);
      const email = String(body.email || '').trim().toLowerCase().slice(0, 160);
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return sendJson(res, 400, { error: 'সঠিক ইমেইল দিন' });
      if (!mailConfigured()) return sendJson(res, 503, { error: 'এই মুহূর্তে OTP পাঠানো যাচ্ছে না। Support-এর সঙ্গে যোগাযোগ করুন।', support: true });
      const now = Date.now();
      const ip = clientIp(req);
      const h = otpIpHits.get(ip) || { n: 0, first: now };
      if (now - h.first > 15 * 60 * 1000) { h.n = 0; h.first = now; }
      if (++h.n > 6) return sendJson(res, 429, { error: 'অনেকবার চেষ্টা হয়েছে। ১৫ মিনিট পরে আবার চেষ্টা করুন।', support: true });
      otpIpHits.set(ip, h);
      const user = customers.find(u => u.email === email);
      const old = resetOtps.get(email);
      if (user && !(old && now - old.sentAt < 55000)) {
        const otp = String(crypto.randomInt(100000, 1000000));
        resetOtps.set(email, { hash: otpHash(email, otp), expires: now + OTP_TTL_MS, tries: 0, sentAt: now });
        try { await sendOtpMail(email, otp); }
        catch (e) {
          resetOtps.delete(email);
          console.error('OTP mail error:', e && e.message);
          return sendJson(res, 502, { error: 'ইমেইল পাঠানো যায়নি। কিছুক্ষণ পরে আবার চেষ্টা করুন।', support: true });
        }
      }
      return sendJson(res, 200, { ok: true });
    }
    if (req.method === 'POST' && pathname === '/api/auth/reset') {
      const body = await readJson(req, 4096);
      const email = String(body.email || '').trim().toLowerCase().slice(0, 160);
      const otp = String(body.otp || '').trim();
      const password = String(body.password || '');
      if (!/^\d{6}$/.test(otp)) return sendJson(res, 400, { error: 'OTP ৬ সংখ্যার হতে হবে' });
      if (password.length < 8 || password.length > 128) return sendJson(res, 400, { error: 'পাসওয়ার্ড ৮–১২৮ অক্ষরের হতে হবে' });
      const rec = resetOtps.get(email);
      const user = customers.find(u => u.email === email);
      if (!rec || !user || rec.expires < Date.now()) {
        resetOtps.delete(email);
        return sendJson(res, 400, { error: 'OTP ভুল বা মেয়াদ শেষ। আবার OTP পাঠান।' });
      }
      if (++rec.tries > 5) {
        resetOtps.delete(email);
        return sendJson(res, 429, { error: 'অনেকবার ভুল OTP দেওয়া হয়েছে। Support-এর সঙ্গে যোগাযোগ করুন।', support: true });
      }
      if (!safeEq(rec.hash, otpHash(email, otp))) return sendJson(res, 400, { error: 'OTP ঠিক নয় (' + rec.tries + '/5)', support: rec.tries >= 3 });
      resetOtps.delete(email);
      user.salt = crypto.randomBytes(16).toString('hex');
      user.passwordHash = await passwordHash(password, user.salt);
      saveCustomers();
      customerSessions.deleteWhere(function (v) { return v.userId === user.id; });
      Array.from(customerLoginFails.keys()).forEach(function (k) { if (String(k).indexOf(email + '|') === 0) customerLoginFails.delete(k); });
      const token = crypto.randomBytes(32).toString('hex');
      customerSessions.set(token, { userId: user.id, expires: Date.now() + 7 * 24 * 60 * 60 * 1000 });
      setCustomerCookie(res, token); trustDevice(req, res, user);
      return sendJson(res, 200, { loggedIn: true, user: await withBalance(customerPublic(user)) });
    }

    if (req.method === 'POST' && pathname === '/api/admin/login') {
      if (!ADMIN_PASSWORD) return sendJson(res, 503, { error: 'Render এ FFX-PASS সেট করা নেই। Environment এ FFX-PASS যোগ করে আবার Deploy করুন।' });
      const ip = clientIp(req);
      const wait = lockedFor(ip);
      if (wait > 0) return sendJson(res, 429, { error: 'অনেকবার ভুল হয়েছে। ' + Math.ceil(wait / 60000) + ' মিনিট পরে আবার চেষ্টা করুন।' });
      const body = await readJson(req, 4096);
      if (typeof body.password === 'string' && safeEq(body.password, ADMIN_PASSWORD)) {
        fails.delete(ip);
        const t = makeToken();
        return sendJson(res, 200, { token: t.token, expires: t.expires });
      }
      recordFail(ip);
      await new Promise(function (r) { setTimeout(r, 500); });
      return sendJson(res, 401, { error: 'পাসওয়ার্ড ঠিক নেই' });
    }

    if (!pathname.startsWith('/api/admin/')) return sendJson(res, 404, { error: 'Not found' });
    if (!isAuthed(req)) return sendJson(res, 401, { error: 'লগইন করুন' });

    if (req.method === 'GET' && pathname === '/api/admin/config') {
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/packages') {
      const body = await readJson(req, 128 * 1024);
      const cur = Object.assign({}, (config.prod || {}).ff, { packages: body.packages });
      const prod = Object.assign({}, config.prod, { ff: sanitizeProd(cur) });
      await commit(Object.assign({}, config, { prod: prod }), 'Update FF Like packages', [], []);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/custom') {
      const body = await readJson(req, 4096);
      const list = (config.custom || []).slice();
      if (body.action === 'add') {
        if (list.length >= CUSTOM_MAX) throw new Error('সর্বোচ্চ ' + CUSTOM_MAX + 'টি নতুন প্রোডাক্ট রাখা যাবে');
        const name = String(body.name || '').trim().slice(0, 80);
        if (!name) throw new Error('প্রোডাক্টের নাম লিখুন');
        const id = newCustomId(list);
        const np = getDefaults().np || {};
        list.push(sanitizeCustomItem({ id: id, name: name, packages: [{ label: 'Package 1', name: '', price: 10 }], rules: np.rules || [] }));
        await commit(Object.assign({}, config, { custom: list }), 'Add product ' + name, [], []);
        const out = currentView(); out.newKey = customKey(id);
        return sendJson(res, 200, out);
      }
      if (body.action === 'delete') {
        const cx = findCustom(body.key);
        if (!cx) throw new Error('প্রোডাক্ট পাওয়া যায়নি');
        const rest = list.filter(function (x) { return x.id !== cx.id; });
        await commit(Object.assign({}, config, { custom: rest.length ? rest : null }), 'Delete product ' + cx.name, [], cx.img ? [cx.img] : []);
        return sendJson(res, 200, currentView());
      }
      if (body.action === 'hideNp') {
        await commit(Object.assign({}, config, { hideNp: !!body.value }), (body.value ? 'Hide' : 'Show') + ' New Product card', [], []);
        return sendJson(res, 200, currentView());
      }
      return sendJson(res, 400, { error: 'ভুল কাজ' });
    }

    if (req.method === 'POST' && pathname === '/api/admin/product') {
      const body = await readJson(req, 128 * 1024);
      const cxp = findCustom(body.key);
      if (cxp) {
        const patch = (body.patch && typeof body.patch === 'object') ? body.patch : {};
        const cur = Object.assign({}, cxp);
        ['name', 'title', 'pill', 'packages', 'rules'].forEach(function (f) {
          if (!(f in patch)) return;
          if (patch[f] === null || patch[f] === '') { if (f === 'title' || f === 'pill') delete cur[f]; return; }
          cur[f] = patch[f];
        });
        const clean = sanitizeCustomItem(cur);
        const nl = (config.custom || []).map(function (x) { return x.id === cxp.id ? clean : x; });
        await commit(Object.assign({}, config, { custom: nl }), 'Update product ' + clean.name, [], []);
        return sendJson(res, 200, currentView());
      }
      const p = PRODUCTS.filter(function (x) { return x.key === body.key; })[0];
      if (!p) return sendJson(res, 400, { error: 'প্রোডাক্ট পাওয়া যায়নি' });
      const patch = (body.patch && typeof body.patch === 'object') ? body.patch : {};
      const cur = Object.assign({}, (config.prod || {})[p.key]);
      ['name', 'title', 'pill', 'packages', 'rules'].forEach(function (f) {
        if (!(f in patch)) return;
        if (patch[f] === null || patch[f] === '') delete cur[f]; else cur[f] = patch[f];
      });
      const clean = sanitizeProd(cur);
      const prod = Object.assign({}, config.prod);
      if (Object.keys(clean).length) prod[p.key] = clean; else delete prod[p.key];
      await commit(Object.assign({}, config, { prod: Object.keys(prod).length ? prod : null }), 'Update product ' + p.key, [], []);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/texts') {
      const body = await readJson(req, 32 * 1024);
      const T = Object.assign({}, config.texts);
      Object.keys(body.texts || {}).forEach(function (id) {
        const t = TEXTS.filter(function (x) { return x.id === id; })[0];
        if (!t) throw new Error('ভুল ফিল্ড');
        let v = String(body.texts[id] == null ? '' : body.texts[id]).trim().slice(0, t.max);
        if (t.url) v = cleanUrl(v);
        if (v) T[id] = v; else delete T[id];
      });
      await commit(Object.assign({}, config, { texts: Object.keys(T).length ? T : null }), 'Update texts', [], []);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/upload') {
      const body = await readJson(req, Math.ceil(MAX_UPLOAD_BYTES * 1.4) + 1024);
      const cxu = findCustom(body.kind);
      if (cxu) {
        const mu = /^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/=]+)$/.exec(String(body.dataUrl || ''));
        if (!mu) return sendJson(res, 400, { error: 'শুধু PNG, JPG বা WEBP ছবি দিন' });
        const bu = Buffer.from(mu[2], 'base64');
        if (bu.length > MAX_UPLOAD_BYTES) return sendJson(res, 413, { error: 'ছবি ৩MB এর বেশি বড়' });
        const eu = detectImage(bu);
        if (!eu) return sendJson(res, 400, { error: 'ছবিটা ঠিক নেই' });
        const fu = 'img-' + cxu.id + '-' + Date.now() + '.' + eu;
        const nl = config.custom.map(function (x) { return x.id === cxu.id ? Object.assign({}, x, { img: fu }) : x; });
        await commit(Object.assign({}, config, { custom: nl }), 'Update product picture', [{ name: fu, buf: bu }], cxu.img ? [cxu.img] : []);
        return sendJson(res, 200, currentView());
      }
      if (IMG_KEYS.indexOf(body.kind) === -1) return sendJson(res, 400, { error: 'ভুল ধরন' });
      const kind = IMAGES[body.kind];
      const m = /^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/=]+)$/.exec(String(body.dataUrl || ''));
      if (!m) return sendJson(res, 400, { error: 'শুধু PNG, JPG বা WEBP ছবি দিন' });
      const buf = Buffer.from(m[2], 'base64');
      if (buf.length > MAX_UPLOAD_BYTES) return sendJson(res, 413, { error: 'ছবি ৩MB এর বেশি বড়' });
      const ext = detectImage(buf);
      if (!ext) return sendJson(res, 400, { error: 'ছবিটা ঠিক নেই' });
      const fname = kind.prefix + '-' + Date.now() + '.' + ext;
      const old = imgGet(config, body.kind);
      const next = Object.assign({}, config);
      imgSet(next, body.kind, fname);
      await commit(next, 'Update ' + kind.prefix, [{ name: fname, buf: buf }], old ? [old] : []);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/quick') {
      const body = await readJson(req, 8 * 1024);
      const next = Object.assign({}, config, { quick: sanitizeQuick(body.items) });
      await commit(next, 'Update quick buttons', [], []);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/banner') {
      const body = await readJson(req, Math.ceil(MAX_UPLOAD_BYTES * 1.4) + 1024);
      const act = body.action;
      const list = bannerList().slice();
      const add = [], del = [];
      const idx = Number(body.index);
      const readImg = function () {
        const m = /^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/=]+)$/.exec(String(body.dataUrl || ''));
        if (!m) throw new Error('শুধু PNG, JPG বা WEBP ছবি দিন');
        const buf = Buffer.from(m[2], 'base64');
        if (buf.length > MAX_UPLOAD_BYTES) throw new Error('ছবি ৩MB এর বেশি বড়');
        const ext = detectImage(buf);
        if (!ext) throw new Error('ছবিটা ঠিক নেই');
        return { name: 'banner-' + Date.now() + '-' + Math.floor(Math.random() * 10000) + '.' + ext, buf: buf };
      };
      const okIdx = function (i) { return Number.isInteger(i) && i >= 0 && i < list.length; };
      if (act === 'add') {
        if (list.length >= MAX_BANNERS) throw new Error('সর্বোচ্চ ' + MAX_BANNERS + 'টি ব্যানার রাখা যাবে');
        const f = readImg(); add.push(f); list.push(f.name);
      } else if (act === 'replace') {
        if (!okIdx(idx)) throw new Error('ব্যানার পাওয়া যায়নি');
        const f = readImg(); add.push(f);
        const old = list[idx]; list[idx] = f.name;
        if (isUploaded(old)) del.push(old);
      } else if (act === 'delete') {
        if (list.length <= 1) throw new Error('কমপক্ষে ১টি ব্যানার রাখতে হবে');
        if (!okIdx(idx)) throw new Error('ব্যানার পাওয়া যায়নি');
        const old = list.splice(idx, 1)[0];
        if (isUploaded(old)) del.push(old);
      } else if (act === 'move') {
        const to = idx + (body.dir === 'up' ? -1 : 1);
        if (!okIdx(idx) || to < 0 || to >= list.length) throw new Error('সরানো যাচ্ছে না');
        const t = list[idx]; list[idx] = list[to]; list[to] = t;
      } else {
        throw new Error('ভুল কাজ');
      }
      const next = Object.assign({}, config, { banners: list });
      await commit(next, 'Update banners', add, del);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/reset') {
      const body = await readJson(req, 4096);
      const next = Object.assign({}, config);
      let del = [];
      const cxr = findCustom(body.kind);
      if (cxr) {
        next.custom = config.custom.map(function (x) { if (x.id !== cxr.id) return x; const y = Object.assign({}, x); delete y.img; return y; });
        if (cxr.img) del = [cxr.img];
        await commit(next, 'Reset product picture', [], del);
        return sendJson(res, 200, currentView());
      }
      if (body.kind === 'packages' || body.kind === 'product') {
        const key = body.kind === 'packages' ? 'ff' : body.key;
        const prod = Object.assign({}, config.prod);
        if (body.kind === 'packages') { const c = Object.assign({}, prod.ff); delete c.packages; if (Object.keys(c).length) prod.ff = c; else delete prod.ff; }
        else delete prod[key];
        next.prod = Object.keys(prod).length ? prod : null;
      } else if (body.kind === 'text') {
        const T = Object.assign({}, config.texts); delete T[body.id];
        next.texts = Object.keys(T).length ? T : null;
      } else if (body.kind === 'quick') {
        next.quick = null;
      } else if (body.kind === 'banners') {
        del = (config.banners || []).filter(isUploaded);
        next.banners = null;
      } else {
        if (IMG_KEYS.indexOf(body.kind) === -1) return sendJson(res, 400, { error: 'ভুল ধরন' });
        const old = imgGet(config, body.kind);
        if (old) del = [old];
        imgSet(next, body.kind, null);
      }
      await commit(next, 'Reset ' + String(body.kind), [], del);
      return sendJson(res, 200, currentView());
    }

    if (req.method === 'POST' && pathname === '/api/admin/resync') {
      ready = initStorage();
      await ready;
      return sendJson(res, 200, currentView());
    }

    return sendJson(res, 404, { error: 'Not found' });
  } catch (e) {
    if (e && e.message === 'too_large') return sendJson(res, 413, { error: 'ডাটা অনেক বড়' });
    if (e && e.message === 'bad_json') return sendJson(res, 400, { error: 'ভুল ডাটা' });
    return sendJson(res, 400, { error: (e && e.message) || 'কিছু একটা সমস্যা হয়েছে' });
  }
}

const server = http.createServer((req, res) => {
  Promise.all([ready, customersLoaded]).then(function () { handle(req, res); }).catch(function () {
    try { res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end('500 Internal Server Error'); } catch (e) {}
  });
});

function handle(req, res) {
  let pathname;
  try {
    pathname = decodeURI(req.url.split('?')[0]);
  } catch (e) {
    res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
    return res.end('400 Bad Request');
  }

  if (pathname.startsWith('/api/')) {
    return handleApi(req, res, pathname);
  }

  // ---- অ্যাডমিন অ্যাপ (PWA): আলাদা manifest, আইকন ও service worker (শুধু /admin এর জন্য) ----
  if (pathname === '/manifest.json') {
    const man = {
      id: '/', name: 'TIGER LEGEND TOPUP', short_name: 'TIGER LEGEND',
      start_url: '/', scope: '/', display: 'standalone', orientation: 'portrait',
      background_color: '#ffffff', theme_color: '#1e63f0',
      icons: [
        { src: '/icon-192.png?v=2', sizes: '192x192', type: 'image/png', purpose: 'any' },
        { src: '/icon-512.png?v=2', sizes: '512x512', type: 'image/png', purpose: 'any' }
      ]
    };
    res.writeHead(200, { 'Content-Type': 'application/manifest+json; charset=utf-8', 'Cache-Control': 'no-cache' });
    return res.end(JSON.stringify(man));
  }
  if (pathname === '/admin-manifest.json') {
    const man = {
      id: '/admin', name: ADMIN_APP_NAME, short_name: ADMIN_APP_SHORT,
      description: 'Admin panel', start_url: '/admin', scope: '/admin',
      display: 'standalone', orientation: 'portrait',
      background_color: '#f5f8ff', theme_color: '#2563eb',
      icons: [
        { src: '/admin-icon-192.png?v=2', sizes: '192x192', type: 'image/png', purpose: 'any' },
        { src: '/admin-icon-512.png?v=2', sizes: '512x512', type: 'image/png', purpose: 'any' },
        { src: '/admin-icon-512.png?v=2', sizes: '512x512', type: 'image/png', purpose: 'maskable' }
      ]
    };
    const body = JSON.stringify(man);
    res.writeHead(200, { 'Content-Type': 'application/manifest+json; charset=utf-8', 'Cache-Control': 'no-cache', 'X-Robots-Tag': 'noindex, nofollow' });
    return res.end(body);
  }
  if (pathname === '/admin-icon-192.png' || pathname === '/admin-icon-512.png') {
    const aIcon = path.join(ROOT_DIR, pathname);
    if (fs.existsSync(aIcon)) { res.writeHead(200, { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=300', 'X-Robots-Tag': 'noindex, nofollow' }); return res.end(fs.readFileSync(aIcon)); }
    const png = Buffer.from(pathname === '/admin-icon-192.png' ? ADMIN_ICON_192_B64 : ADMIN_ICON_512_B64, 'base64');
    res.writeHead(200, { 'Content-Type': 'image/png', 'Content-Length': png.length, 'Cache-Control': 'public, max-age=86400', 'X-Robots-Tag': 'noindex, nofollow' });
    return res.end(png);
  }
  if (pathname === '/admin-sw.js') {
    res.writeHead(200, { 'Content-Type': 'application/javascript; charset=utf-8', 'Cache-Control': 'no-cache', 'X-Robots-Tag': 'noindex, nofollow' });
    return res.end(ADMIN_SW_JS);
  }

  if (pathname === '/admin' || pathname === '/admin/') {
    const f = path.join(ROOT_DIR, 'admin.html');
    return fs.readFile(f, function (err, data) {
      if (err) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        return res.end('admin.html পাওয়া যায়নি');
      }
      res.writeHead(200, {
        'Content-Type': MIME_TYPES['.html'],
        'Cache-Control': 'no-store',
        'X-Robots-Tag': 'noindex, nofollow',
        'X-Frame-Options': 'DENY',
        'Referrer-Policy': 'no-referrer'
      });
      res.end(data);
    });
  }

  if (pathname.startsWith('/uploads/')) {
    const name = pathname.slice('/uploads/'.length);
    if (!SAFE_FILE.test(name)) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('404 Not Found');
    }
    return serveFile(path.join(UPLOAD_DIR, name), res, 'public, max-age=31536000, immutable');
  }

  // লগইন পেজ: /login, /login/ ও /login.html সরাসরি login.html খুলবে (হোমপেজে যাবে না)
  if (pathname === '/login' || pathname === '/login/' || pathname === '/login.html') {
    return fs.readFile(path.join(ROOT_DIR, 'login.html'), function (err, data) {
      if (err) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        return res.end('login.html পাওয়া যায়নি');
      }
      res.writeHead(200, {
        'Content-Type': MIME_TYPES['.html'],
        'Cache-Control': 'no-store',
        'X-Robots-Tag': 'noindex, nofollow',
        'X-Frame-Options': 'DENY',
        'Referrer-Policy': 'no-referrer'
      });
      res.end(data);
    });
  }

  if (pathname === '/' || pathname === '' || pathname === '/index.html' || pathname === '/FFX.html') {
    return sendHome(req, res);
  }

  // অ্যাপ আইকন: আগে রিপোতে আপলোড করা icon-192.png / icon-512.png ফাইল, না থাকলে কোডের ভেতরের ডিফল্ট আইকন
  if (pathname === '/icon-192.png' || pathname === '/icon-512.png') {
    const iconFile = path.join(ROOT_DIR, pathname);
    if (fs.existsSync(iconFile)) return serveFile(iconFile, res, 'no-cache');
    const png = Buffer.from(pathname === '/icon-192.png' ? ICON_192_B64 : ICON_512_B64, 'base64');
    res.writeHead(200, { 'Content-Type': 'image/png', 'Content-Length': png.length, 'Cache-Control': 'no-cache' });
    return res.end(png);
  }

  const filePath = path.normalize(path.join(ROOT_DIR, pathname));
  const rel = path.relative(ROOT_DIR, filePath);
  const base = path.basename(filePath).toLowerCase();
  const insideData = filePath === DATA_DIR || filePath.startsWith(DATA_DIR + path.sep);
  if (rel.startsWith('..') || path.isAbsolute(rel)) {
    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
    return res.end('403 Forbidden');
  }
  if (insideData || BLOCKED_NAMES.has(base) || base.startsWith('.') || rel.split(path.sep).some(function (p) { return BLOCKED_DIRS.has(p) || p.startsWith('.'); })) {
    return sendHome(req, res);
  }

  // আগে public/ ফোল্ডারে খোঁজা হবে (যেমন /js/user-system.js → public/js/user-system.js), তারপর মূল ফোল্ডারে
  const pubPath = path.normalize(path.join(PUBLIC_DIR, pathname));
  const candidates = pubPath.startsWith(PUBLIC_DIR + path.sep) ? [pubPath, filePath] : [filePath];
  (function tryNext(i) {
    if (i >= candidates.length) {
      // ফাইল না পেলে: .js/.css/ছবি ইত্যাদির জন্য সঠিক 404 (হোমপেজের HTML নয়), বাকি পাথে হোমপেজ
      const ext = path.extname(pathname).toLowerCase();
      if (ext && ext !== '.html') {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        return res.end('404 Not Found');
      }
      return sendHome(req, res);
    }
    fs.stat(candidates[i], (err, stats) => {
      if (err || !stats.isFile()) return tryNext(i + 1);
      serveFile(candidates[i], res, 'public, max-age=3600');
    });
  })(0);
}

function serveFile(filePath, res, cache) {
  const ext = path.extname(filePath).toLowerCase();
  const contentType = MIME_TYPES[ext] || 'application/octet-stream';

  const stream = fs.createReadStream(filePath);
  stream.on('open', () => {
    res.setHeader('Content-Type', contentType);
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Cache-Control', cache || 'public, max-age=3600');
    stream.pipe(res);
  });
  stream.on('error', () => {
    if (!res.headersSent) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('404 Not Found');
    } else {
      res.end();
    }
  });
}

server.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running on port ${PORT}`);
  if (!ADMIN_PASSWORD) console.log('⚠️  FFX-PASS সেট করা নেই — /admin লগইন বন্ধ থাকবে');
  try {
    const tgs = require('./services/telegram');
    const tgBase = process.env.PUBLIC_URL || process.env.RENDER_EXTERNAL_URL || '';
    tgs.setupWebhook(tgBase).then(function (ok) { if (!ok && tgBase) setTimeout(function () { tgs.setupWebhook(tgBase); }, 15000); }).catch(function () {});
  } catch (e) { console.error('Telegram setup error:', e && e.message); }
  console.log(USE_GH ? 'Storage: GitHub (' + (GH_REPO || '?') + ' @ ' + GH_BRANCH + ')' : 'Storage: লোকাল (FFX-G সেট করা নেই)');
});
